import{_ as e,c as p,o as r,af as s}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"15、【謙】 艮下坤上","description":"周易尚氏學 - 15、【謙】 艮下坤上","frontmatter":{"title":"15、【謙】 艮下坤上","description":"周易尚氏學 - 15、【謙】 艮下坤上"},"headers":[],"relativePath":"classics/shangshi/020.md","filePath":"classics/shangshi/020.md"}'),i={name:"classics/shangshi/020.md"};function t(h,a,n,l,c,o){return r(),p("div",null,[...a[0]||(a[0]=[s('<h1 id="_15、【謙】-艮下坤上" tabindex="-1">15、【謙】 艮下坤上 <a class="header-anchor" href="#_15、【謙】-艮下坤上" aria-label="Permalink to “15、【謙】 艮下坤上”">​</a></h1><p>山本高而在地下。故曰謙。謙不自足也。三承乘皆陰。故曰亨。艮為君子。坤為終。故曰君子有終。謙嗛同。漢書藝文志易之嗛嗛。尹翁歸傳。溫良嗛退。注皆雲同謙。嗛不足也。少也。故彖傳以盈為對文。</p><p>彖曰。謙亨。天道下濟而光明。地道卑而上行。天道虧盈而益謙。地道變盈而流謙。鬼神害盈而福謙。人道惡盈而好謙。謙尊而光。卑而不可踰。君子之終也。</p><p>艮為天。為光明。(象本易林。實易以艮為天為光明之處甚多。詳焦氏易詁。荀爽謂陽來成坎。日月之象。故光明。非。)居下卦。故曰下濟。濟止也。言一陽止於三而成艮也。艮止也。坤為卑。居上卦。故曰卑而上行。互震為行也。天道虧盈四句。申有終之原理。變毀也。坤為虧。為毀。為害。為惡。為鬼。震為神。(象失傳。詳焦氏易詁)為人。艮一陽在上。故尊。(艮為官。為君子。人知之。乃為尊又不知。只易林以艮為貴為尊。)而光。卑謂居下卦。虞翻謂三位賤。故卑。非也。卑而不可踰者。艮為山。艮止坎險。故雖卑退。而不能踰越。終獲福也。</p><p>象曰。地中有山。謙。君子以捊多益寡。稱物平施。</p><p>捊王弼本作裒。釋文雲。鄭荀董蜀才皆作捋。取也。捊裒音同通用。陽來內故曰益。艮手故曰取。說卦坤為眾。故為多。剝下五陰。互三坤。多極矣。今上來益三。居中以界上下。坤為物。下物雖寡。陽來益之。上下物等。故曰稱物。坎為平。物稱故施平。(虞因艮多節謂艮為多。非。多白眼。多心。多眚。多字若可取象。則巽坎皆可為多。不只艮也。)</p><p>初六。謙謙君子。用涉大川。吉。</p><p>初臨坎水。坎險坎陷。本不易涉。然初居下卦之下。謙而又謙。卑以自牧。故可用以涉此大川。而無不吉也。### 象曰。謙謙君子。卑以自牧也。 揚子方言。牧司也。治也。</p><p>六二。鳴謙。貞吉。</p><p>玉篇。鳴聲相命也。震為鳴。二承之。三陽為二友。損。一人行則得其友。是也。詩小雅。嚶其鳴矣。求其友聲。言二得承三。遂其所願。故得意而嗚也。二當位。故貞吉。</p><h3 id="象曰。鳴謙貞吉。中心得也。" tabindex="-1">象曰。鳴謙貞吉。中心得也。 <a class="header-anchor" href="#象曰。鳴謙貞吉。中心得也。" aria-label="Permalink to “象曰。鳴謙貞吉。中心得也。”">​</a></h3><p>中心得。申鳴謙之故也。卦體坎。坎為中為心。</p><p>九三。勞謙。君子有終。吉。</p><p>坎為勞卦。故曰勞謙。艮為君子。艮成終。故曰君子有終。</p><h3 id="象曰。勞謙君子。萬民服也。" tabindex="-1">象曰。勞謙君子。萬民服也。 <a class="header-anchor" href="#象曰。勞謙君子。萬民服也。" aria-label="Permalink to “象曰。勞謙君子。萬民服也。”">​</a></h3><p>三臨群陰。坤眾故曰萬民服。</p><p>六四。無不利。撝謙。</p><p>釋文撝麾同。指撝也。</p><h3 id="象曰。無不利撝謙。不違則也。" tabindex="-1">象曰。無不利撝謙。不違則也。 <a class="header-anchor" href="#象曰。無不利撝謙。不違則也。" aria-label="Permalink to “象曰。無不利撝謙。不違則也。”">​</a></h3><p>則謂三。言四順三。而發撝其謙德也。陰順陽。故無不利。子夏傳撝謙化謙也。蓋化於三而不違之也。則純指三言。各家泛論之。非也。</p><p>六五。不當。句以其鄰。利用侵伐。無不利。</p><p>坤虛故不當。震為鄰。為侵伐。以。與也。言五與四順三以徵不服。無不利也。震為威武。故為侵伐為徵。李鼎柞謂六五離爻。離為戈兵。故為侵伐。毛奇齡惠棟用之。非也。</p><h3 id="象曰。利用侵伐。徵不服也。" tabindex="-1">象曰。利用侵伐。徵不服也。 <a class="header-anchor" href="#象曰。利用侵伐。徵不服也。" aria-label="Permalink to “象曰。利用侵伐。徵不服也。”">​</a></h3><p>上六反君道。故曰不服。荀爽謂指五似非。</p><p>上六。鳴謙。利用行師。徵邑國。</p><p>俞樾雲。六二鳴謙。傳曰中心得。此曰志未得。何相反若是。疑鳴當作冥。與豫升上六同例。按俞說是也。豫上六冥豫。釋文雲鄭讀為嗚。鳴冥古蓋同聲相假。猶捊之作裒也。坤為師為邑國。震為徵為行。人眾勢強故利。然以冥謙行之。昧於事情。故難得志。宋襄公是也。</p><h3 id="象曰。嗚謙。志未得也。可用行師。徵邑國也。" tabindex="-1">象曰。嗚謙。志未得也。可用行師。徵邑國也。 <a class="header-anchor" href="#象曰。嗚謙。志未得也。可用行師。徵邑國也。" aria-label="Permalink to “象曰。嗚謙。志未得也。可用行師。徵邑國也。”">​</a></h3><p>上應在三。三坎為志。志未得。言上為四五所阻。應三難也。</p>',28)])])}const f=e(i,[["render",t]]);export{_ as __pageData,f as default};
